"                        <div className="ml-auto flex items-center gap-3">
                          <button
                            id="loyalty-popup-button"
                            onClick={() => {
                              if (customerPhone) {
                                const fullPhone = customerPhone.startsWith('+') ? customerPhone : customerCountryCode + customerPhone;
                                refreshCustomerHistory(fullPhone);
                                setIsCustomerHistoryModalOpen(true);
                              } else {
                                toast.error("Please select or enter a customer mobile number to view history.");
                              }
                            }}
                            className={`transition-colors ${isDark ? 'text-gray-400 hover:text-white' : 'text-slate-700 hover:text-black'}`}
                            title="View Loyalty/Points History"
                          >
                            <Gift size={18} />
                          </button>
                          <button onClick={async () => { setIsCouponModalOpen(true); try { const res = await posService.getCoupons(localStorage.getItem('pos_outlet_id')); setAvailableCoupons(res.data || []); } catch (err) { setAvailableCoupons([]); } }} className={`transition-colors ${appliedCoupon ? 'text-emerald-500' : (isDark ? 'text-gray-400 hover:text-white' : 'text-slate-700 hover:text-black')}`}><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M21 5H3a2 2 0 0 0-2 2v3a2 2 0 0 1 0 4v3a2 2 0 0 0 2 2h18a2 2 0 0 0 2-2v-3a2 2 0 0 1 0-4V7a2 2 0 0 0-2-2Z"/><path d="M8 6v12" strokeDasharray="2 2"/><circle cx="12.5" cy="10.5" r="1.2" fill="currentColor"/><path d="M11.5 14.5 16.5 9.5"/><circle cx="15.5" cy="13.5" r="1.2" fill="currentColor"/></svg></button>
                        </div>"
